with with_windows as (select *, row_number() over w_hist as event_seq, dense_rank() over w_grp as shipping_fee_dense_rank from orders window w_hist as (partition by status order by shipping_fee, id), w_grp as (partition by customer_id order by shipping_fee)) select id, customer_id, store_id, order_date, status, channel, shipping_fee, event_seq, shipping_fee_dense_rank, case when channel rlike '^(partner|store)$' then 'OTHER_ZONE' else 'GROUP_A' end as channel_zone from with_windows;
